with matched_keys as (select city, id from customers except distinct select city, id from customers where lower(name) like '%vy %'), verified as (select s.* from customers s join matched_keys k on s.city = k.city and s.id = k.id) select case when age >= 61 then 'LARGE' else 'SMALL' end as age_tier, segment, case when credit_limit >= 18000 then 'HIGH' else 'LOW' end as credit_limit_tier, sum(age) filter (where city = 'Berlin') as berlin_total_age, sort_array(collect_set(segment)) as segment_list, max(credit_limit) filter (where city = 'London') as london_max_credit_limit, count(*) filter (where country = 'DE') as de_rows, grouping_id() as grouping_level from verified group by rollup (case when age >= 61 then 'LARGE' else 'SMALL' end, segment, case when credit_limit >= 18000 then 'HIGH' else 'LOW' end) having berlin_total_age < 0;
